import { Video } from "../types.js";

// Subtitles saved with a video: the tracks the Download form offers for the
// link it probed, and how the pick is passed on.

/** One caption track of a video: uploaded by its author, or generated by the site. */
export type SubtitleTrack = { code: string; automatic: boolean; title: string };

/** How the picked track is kept: inside the video file, or as an `.srt` file next to it. */
export type SubtitlePick = { code: string; automatic: boolean; embed: boolean };

/** Uploaded tracks listed at most; a video rarely has more, and the dropdown lists each twice. */
const MAX_UPLOADED = 40;

function languageName(code: string): string {
  try {
    return new Intl.DisplayNames(["en"], { type: "language" }).of(code) ?? code;
  } catch {
    return code;
  }
}

/**
 * The tracks to offer: every uploaded one, then the site's own transcription
 * of what is spoken (YouTube's `<lang>-orig`) and its English track. YouTube
 * lists an automatic translation into every language it knows; those are left
 * out, as the rate limit on them makes most downloads fail.
 */
export function subtitleTracks(video: Video): SubtitleTrack[] {
  const uploaded = Object.keys(video.subtitles ?? {})
    .filter((code) => code !== "live_chat")
    .slice(0, MAX_UPLOADED)
    .map((code) => ({ code, automatic: false, title: languageName(code) }));
  const automatic = Object.keys(video.automatic_captions ?? {});
  const spoken = video.language?.split(/[-_]/)[0]?.toLowerCase();
  const generated: SubtitleTrack[] = [];
  for (const lang of [...new Set([spoken, "en"])]) {
    if (!lang) continue;
    const code = automatic.find((c) => c === `${lang}-orig`) ?? automatic.find((c) => c === lang);
    if (code && !generated.some((track) => track.code === code)) {
      generated.push({ code, automatic: true, title: `${languageName(lang)} (auto-generated)` });
    }
  }
  return [...uploaded, ...generated];
}

/** The Subtitles dropdown's value for a track and where it goes. */
export function subtitleValue(track: SubtitleTrack, embed: boolean): string {
  return `${embed ? "embed" : "file"}|${track.automatic ? "auto" : "sub"}|${track.code}`;
}

/** Read a Subtitles dropdown value back; `undefined` for "None" or anything else. */
export function parseSubtitleValue(value: unknown): SubtitlePick | undefined {
  const match = /^(embed|file)\|(auto|sub)\|(.+)$/.exec(typeof value === "string" ? value : "");
  if (!match) return undefined;
  return { embed: match[1] === "embed", automatic: match[2] === "auto", code: match[3] };
}

const escapeRegExp = (text: string) => text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

/**
 * yt-dlp arguments for the pick. Exactly one track is asked for (`--sub-langs`
 * is a regex, so the code is escaped). Embedding keeps WebVTT, the one format
 * a WebM file can hold and one MP4 and MKV take too; a separate file is
 * converted to `.srt`, which every player and editor reads.
 *
 * `--embed-subs` fetches uploaded captions by itself and removes the caption
 * file once it's inside the video; with `--write-subs` next to it yt-dlp
 * would leave that file behind, so it's passed only for a separate file.
 */
export function subtitleArgs(pick: SubtitlePick): string[] {
  return [
    ...(pick.automatic ? ["--write-auto-subs"] : pick.embed ? [] : ["--write-subs"]),
    "--sub-langs",
    escapeRegExp(pick.code),
    ...(pick.embed ? ["--sub-format", "vtt/srt/best", "--embed-subs"] : ["--convert-subs", "srt"]),
  ];
}

/** A file yt-dlp's downloader wrote that is a caption track, not a stream of the video. */
export function isSubtitleFile(file: string): boolean {
  return /\.(vtt|srt|ass|ssa|ttml|lrc|sbv|json3|srv[1-3])$/i.test(file);
}
